-- Create this in a BRAND NEW Supabase project. Never execute against other projects.
create table public.chat_sessions (id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'New chat',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.chat_messages (id bigint generated always as identity primary key,session_id uuid not null references public.chat_sessions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('user','assistant')),content text not null,created_at timestamptz not null default now());
create table public.watchlists (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,ticker text not null,notes text not null default '',created_at timestamptz not null default now(),unique(user_id,ticker));
create table public.market_data_snapshots (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,ticker text not null,source text not null,as_of date not null,candles jsonb not null,analysis jsonb not null,verified boolean not null default false,created_at timestamptz not null default now());
create index on public.chat_sessions(user_id,updated_at desc);create index on public.chat_messages(session_id,created_at);create index on public.market_data_snapshots(user_id,ticker,created_at desc);
alter table public.chat_sessions enable row level security;alter table public.chat_messages enable row level security;alter table public.watchlists enable row level security;alter table public.market_data_snapshots enable row level security;
create policy "owner sessions" on public.chat_sessions for all to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
create policy "owner messages" on public.chat_messages for all to authenticated using (user_id=(select auth.uid()) and exists(select 1 from public.chat_sessions s where s.id=session_id and s.user_id=(select auth.uid()))) with check (user_id=(select auth.uid()) and exists(select 1 from public.chat_sessions s where s.id=session_id and s.user_id=(select auth.uid())));
create policy "owner watchlists" on public.watchlists for all to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
create policy "owner snapshots" on public.market_data_snapshots for all to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
